<div class="top"><div><h2 style="margin:0"><?= e($n['title'] ?: 'Note') ?></h2><span class="muted"><a href="/staff/notes">&larr; Notes</a><?= $n['shared'] ? ' &middot; shared with all staff' : '' ?></span></div></div>
<div class="grid g2" style="align-items:start"><div class="card"><?php if ($mine): ?><form method="post" action="/staff/notes/<?= (int) $n['id'] ?>"><?= csrf_field() ?><input type="hidden" name="action" value="save">
<label for="nt">Title</label><input id="nt" name="title" maxlength="160" value="<?= e((string) $n['title']) ?>">
<label for="nb"><?= $n['kind'] === 'list' ? 'Checklist (one item per line)' : 'Note' ?></label><textarea id="nb" name="body" rows="10" maxlength="20000"><?= e($n['kind'] === 'list' ? implode("\n", array_column($items, 't')) : (string) $n['body']) ?></textarea>
<div class="row"><div><label for="nc">Colour</label><select id="nc" name="color"><?= options(NOTE_COLORS, $n['color']) ?></select></div><div><label style="font-weight:400;margin-top:26px"><input type="checkbox" name="shared" value="1" style="width:auto;margin:0 6px 0 0" <?= $n['shared'] ? 'checked' : '' ?>>Share with all staff</label></div></div><button class="btn">Save</button></form>
<form method="post" action="/staff/notes/<?= (int) $n['id'] ?>" class="mt"><?= csrf_field() ?><button class="btn danger sm" name="action" value="delete" data-confirm="Delete this note and its files?">Delete note</button></form>
<?php else: ?><?php if ($n['kind'] === 'list'): foreach ($items as $i => $it): ?><form method="post" action="/staff/notes/<?= (int) $n['id'] ?>" class="tick"><?= csrf_field() ?><input type="hidden" name="action" value="tick"><input type="hidden" name="i" value="<?= $i ?>"><input type="hidden" name="back" value="edit"><label style="font-weight:400"><input type="checkbox" data-autosubmit style="width:auto;margin:0 6px 0 0" <?= $it['d'] ? 'checked' : '' ?>><?= e($it['t']) ?></label></form><?php endforeach; else: ?><?= nl2br(e((string) $n['body'])) ?><?php endif; ?><p class="muted mt">Only the author can edit this note.</p><?php endif; ?></div>
<div class="card"><h3>Files</h3><?php $att = att_for('note', (int) $n['id']); require __DIR__ . '/attachments.php'; ?></div></div>
